const rawText = $input.first().json["Paste The JSON"]; 
const payload = JSON.parse(rawText);
const goalsData = payload.goals || {};
const splitItems = [];

const DEPT_MAP = {
  "Ganesh": "PO department",
  "Shreyash": "SO department",
  "Shruti": "Sales Department",
  "Vaishnavi": "Logistics Department"
};

for (const [name, details] of Object.entries(goalsData)) {
  const dateStr = new Date().toISOString().slice(2, 10).replace(/-/g, '');
  const shortHash = Math.random().toString(36).substring(2, 6).toUpperCase();
  const dept = DEPT_MAP[name] || "Other";
  splitItems.push({
    json: {
      "Task ID": `TSK-${dateStr}-${name.substring(0,3).toUpperCase()}-${shortHash}`,
      "Date": new Date().toLocaleDateString('en-GB'),
      "Task Description": details.goal || details,
      "Assigned To": name,
      "Assigned By": "Manager",
      "Department": dept,
      "Deadline": details.deadline || "",
      "Priority": details.priority || "Normal",
      "Status": "Pending",
      "Reason": "",
      "Source": "Daily Goals Input",
      "Updated By": "n8n Automation",
      "Last Updated": new Date().toISOString()
    }
  });
}
return splitItems;

const rawText = $input.first().json["Paste The JSON"]; 
const payload = JSON.parse(rawText);
const goalsData = payload.goals || {};
const splitItems = [];

for (const [dept, goal] of Object.entries(goalsData)) {
  const dateStr = new Date().toISOString().slice(2, 10).replace(/-/g, '');
  const shortHash = Math.random().toString(36).substring(2, 6).toUpperCase();
  splitItems.push({
    json: {
      "Goal ID": `GOAL-${dateStr}-${dept.substring(0,3).toUpperCase()}-${shortHash}`,
      "Time Frame": "Monthly",
      "Week/Month": new Date().toLocaleString('default', { month: 'long', year: 'numeric' }),
      "Assigned To": dept,
      "Given By": "UI Input / Manager",
      "Goal": goal,
      "Deadline": "End of Month",
      "Status": "Pending",
      "Reason": "",
      "Updated By": "n8n Automation",
      "Last Updated": new Date().toISOString()
    }
  });
}
return splitItems;

const rawInput = $('On form submission').first().json['Paste The JSON'];
let finalTranscript = "";
let individualUpdates = {};

try {
    const parsedData = JSON.parse(rawInput);
    finalTranscript = parsedData.transcript || "";
    individualUpdates = parsedData.individual_updates || {};
} catch (e) {
    finalTranscript = rawInput;
}

let dailyContext = [];
let monthlyContext = [];

try {
    const allTasks = $('Fetch All Tasks Context').all() || [];
    dailyContext = allTasks.map(item => item.json).filter(item => Object.keys(item).length > 0 && item["Task ID"]);
} catch(e) {}

try {
    const rawMonthly = $('Fetch Monthly Context').all() || [];
    monthlyContext = rawMonthly.map(item => item.json).filter(item => Object.keys(item).length > 0 && item["Goal ID"]);
} catch(e) {}

return [{ json: { transcript: finalTranscript, individual_updates: individualUpdates, daily_context: dailyContext, monthly_context: monthlyContext } }];

const text = $input.first().json.text || "";
let cleanText = text;
const firstBrace = cleanText.indexOf('{');
const lastBrace = cleanText.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1) { cleanText = cleanText.substring(firstBrace, lastBrace + 1); }

let parsed = { Tasks: [], Reports: [] };
try { parsed = JSON.parse(cleanText); } catch (e) { console.log("LLM Parse Error:", e); }
const tasks = parsed.Tasks || [];

const DEPT_MAP = { "Ganesh": "PO department", "Shreyash": "SO department", "Shruti": "Sales Department", "Vaishnavi": "Logistics Department" };

return tasks.map(t => {
    const safeName = (t.Assigned_To || "UNK").substring(0,3).toUpperCase();
    const dateStr = new Date().toISOString().slice(2, 10).replace(/-/g, '');
    const shortHash = Math.random().toString(36).substring(2, 6).toUpperCase();
    const taskId = (t.Task_ID && t.Task_ID.trim() !== "") ? t.Task_ID : `TSK-${dateStr}-${safeName}-${shortHash}`;
    const dept = DEPT_MAP[t.Assigned_To] || "Other";
    return { json: { "Task ID": taskId, "Date": new Date().toLocaleDateString('en-GB'), "Task Description": t.Task_Description || "-", "Assigned To": t.Assigned_To || "-", "Assigned By": t.Assigned_By || "-", "Department": dept, "Deadline": t.Deadline || "", "Priority": "Normal", "Status": t.Status || "Pending", "Reason": t.Reason || "", "Source": t.Source || "Meeting Transcript", "Updated By": "n8n Automation", "Last Updated": new Date().toISOString() } };
});

const text = $input.first().json.text || "";
let cleanText = text;
